if (pathname.startsWith('/settings')) {
  // Non-admin users should not see settings pages
  if (!$isAdmin) {
    return 'Доступ запрещен';
  }

  if (pathname === '/settings') {
    return 'Администрирование';
  }
  if (pathname.includes('/periods')) return 'Управление периодами';
