  if (pathname.includes('/articles')) return 'Управление статьями';
  return 'Настройки';
}

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen } from '@testing-library/svelte';
import { writable } from 'svelte/store';
import Layout from './Layout.svelte';

// Mock stores
const mockCurrentUser = writable(null);
const mockIsAdmin = writable(false);
const mockPage = writable({ url: { pathname: '/dashboard' } });

vi.mock('$lib/stores/auth.store', () => ({
  currentUser: mockCurrentUser,
  isAdmin: mockIsAdmin,
  authStore: { logout: vi.fn() }
}));

vi.mock('$app/stores', () => ({
  page: mockPage
}));

vi.mock('$app/navigation', () => ({
  goto: vi.fn()
}));

describe('Layout - Admin Access Control', () => {
  beforeEach(() => {
    // Reset mocks
    mockCurrentUser.set(null);
    mockIsAdmin.set(false);
    mockPage.set({ url: { pathname: '/dashboard' } });
  });

  it('hides References menu item for non-admin users', async () => {
    mockCurrentUser.set({
      id: 1,
      user_name: 'Test User',
      role: 'user'
    });
    mockIsAdmin.set(false);

    render(Layout, { props: {} });

    // Should not show "Справочники" menu item
    expect(screen.queryByText('Справочники')).toBeNull();
  });

  it('shows References menu item for admin users', async () => {
    mockCurrentUser.set({
      id: 1,
      user_name: 'Admin User',
      role: 'admin'
    });
    mockIsAdmin.set(true);

    render(Layout, { props: {} });

    // Should show "Справочники" menu item
    expect(screen.getByText('Справочники')).toBeInTheDocument();
  });

  it('hides Settings icon for non-admin users', async () => {
    mockCurrentUser.set({
      id: 1,
      user_name: 'Test User',
      role: 'user'
    });
    mockIsAdmin.set(false);

    render(Layout, { props: {} });

    // Should not show settings button
    expect(screen.queryByTitle('Настройки')).toBeNull();
  });

  it('shows Settings icon for admin users', async () => {
    mockCurrentUser.set({
      id: 1,
      user_name: 'Admin User',
      role: 'admin'
    });
    mockIsAdmin.set(true);

    render(Layout, { props: {} });

    // Should show settings button
    expect(screen.getByTitle('Настройки')).toBeInTheDocument();
  });

  it('shows access denied title for non-admin users on settings pages', async () => {
    mockCurrentUser.set({
      id: 1,
      user_name: 'Test User',
      role: 'user'
    });
    mockIsAdmin.set(false);
    mockPage.set({ url: { pathname: '/settings' } });

    render(Layout, { props: {} });

    // Should show "Доступ запрещен" in page title
    expect(screen.getByText('Доступ запрещен')).toBeInTheDocument();
  });
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import { render, screen } from '@testing-library/svelte';
import { writable } from 'svelte/store';
import SettingsNavigation from './SettingsNavigation.svelte';

// Mock stores
const mockIsAdmin = writable(false);
const mockPage = writable({ url: { pathname: '/settings' } });

vi.mock('$lib/stores/auth.store', () => ({
  isAdmin: mockIsAdmin
}));

vi.mock('$app/stores', () => ({
  page: mockPage
}));

vi.mock('$app/navigation', () => ({
  goto: vi.fn()
}));

describe('SettingsNavigation - Admin Access Control', () => {
  beforeEach(() => {
    mockIsAdmin.set(false);
  });

  it('hides all categories for non-admin users', async () => {
    mockIsAdmin.set(false);

    render(SettingsNavigation, { props: {} });

    // Should not show any settings categories
    expect(screen.queryByText('Справочники')).toBeNull();
    expect(screen.queryByText('Каталоги')).toBeNull();
    expect(screen.queryByText('Система')).toBeNull();
  });

  it('shows all categories for admin users', async () => {
    mockIsAdmin.set(true);

    render(SettingsNavigation, { props: {} });

    // Should show all settings categories
    expect(screen.getByText('Справочники')).toBeInTheDocument();
    expect(screen.getByText('Каталоги')).toBeInTheDocument();
    expect(screen.getByText('Система')).toBeInTheDocument();
  });

  it('shows reference data items for admin users', async () => {
    mockIsAdmin.set(true);

    render(SettingsNavigation, { props: {} });

    // Should show reference data navigation items
    expect(screen.getByText('Периоды')).toBeInTheDocument();
    expect(screen.getByText('Финансовые центры')).toBeInTheDocument();
    expect(screen.getByText('Центры затрат')).toBeInTheDocument();
  });

  it('shows catalog items for admin users', async () => {
    mockIsAdmin.set(true);

    render(SettingsNavigation, { props: {} });

    // Should show catalog navigation items
    expect(screen.getByText('Номенклатуры')).toBeInTheDocument();
    expect(screen.getByText('Продукты')).toBeInTheDocument();
  });
});

import { describe, it, expect } from 'vitest';
import { load } from './+layout.server';

describe('Settings Layout Server Load - Access Control', () => {
  it('throws 401 error when user is not authenticated', async () => {
    const mockEvent = {
      locals: {
        user: null
      }
    } as any;

    await expect(load(mockEvent)).rejects.toThrow();
  });

  it('throws 403 error when user is not admin', async () => {
    const mockEvent = {
      locals: {
        user: {
          id: 1,
          role: 'user'
        }
      }
    } as any;

    await expect(load(mockEvent)).rejects.toThrow();
  });

  it('allows access for admin users', async () => {
    const mockEvent = {
      locals: {
        user: {
          id: 1,
          role: 'admin'
        }
      }
    } as any;

    const result = await load(mockEvent);

    expect(result).toEqual({
      user: {
        id: 1,
        role: 'admin'
      }
    });
  });
});
